const $=s=>document.querySelector(s);const audio=$('#audio'),voice=$('#voiceInput'),mediaInput=$('#mediaInput'),script=$('#script'),match=$('#matchBtn'),timeline=$('#timeline'),canvas=$('#canvas'),caption=$('#caption');let assets=[],scenes=[];
const fmt=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
function ready(){match.disabled=!(audio.src&&script.value.trim()&&assets.length)}
voice.onchange=()=>{const f=voice.files[0];if(!f)return;audio.src=URL.createObjectURL(f);$('#voiceLabel').textContent=f.name;$('#voiceDrop').style.borderStyle='solid';ready()};script.oninput=ready;
mediaInput.onchange=()=>{for(const f of mediaInput.files){assets.push({name:f.name,type:f.type.startsWith('video/')?'video':'image',url:URL.createObjectURL(f),file:f})}$('#mediaCount').textContent=`${assets.length} file`;$('#mediaStrip').innerHTML=assets.map(a=>`<div class="thumb">${a.type==='image'?`<img src="${a.url}">`:`<video src="${a.url}" muted>`}</div>`).join('');ready()};
match.onclick=()=>{match.disabled=true;match.textContent='Đang chia lời và ghép cảnh…';setTimeout(()=>{const parts=script.value.split(/(?<=[.!?])\s+|\n+/).map(x=>x.trim()).filter(Boolean),total=Number.isFinite(audio.duration)?audio.duration:Math.max(12,parts.length*5),weights=parts.map(x=>Math.max(4,x.split(/\s+/).length)),sum=weights.reduce((a,b)=>a+b,0);let t=0;scenes=parts.map((text,i)=>{const len=i===parts.length-1?total-t:total*weights[i]/sum,s={id:i+1,start:t,end:t+len,text,media:assets[i%assets.length]};t+=len;return s});renderTimeline();showScene(scenes[0]);$('#sceneCount').textContent=`${scenes.length} cảnh`;$('#totalTime').textContent=fmt(total);$('#playBtn').disabled=false;$('#exportBtn').disabled=false;$('#planBtn').disabled=false;match.disabled=false;match.innerHTML='<span>✓</span> Ghép lại timeline'},700)};
function renderTimeline(){timeline.innerHTML=scenes.map(s=>`<button class="scene" data-id="${s.id}"><span>${s.id}</span>${s.media.type==='image'?`<img src="${s.media.url}">`:`<video src="${s.media.url}" muted>`}<div><strong>${fmt(s.start)}–${fmt(s.end)}</strong><p>${s.text}</p></div></button>`).join('');timeline.querySelectorAll('.scene').forEach(b=>b.onclick=()=>{const s=scenes[+b.dataset.id-1];audio.currentTime=s.start;showScene(s)})}
function showScene(s){if(!s)return;canvas.querySelectorAll('img,video,.empty').forEach(x=>x.remove());const el=document.createElement(s.media.type==='image'?'img':'video');el.src=s.media.url;if(el.tagName==='VIDEO'){el.muted=true;el.loop=true;if(!audio.paused)el.play()}canvas.prepend(el);caption.textContent=s.text;caption.style.display='block';timeline.querySelectorAll('.scene').forEach(x=>x.classList.toggle('active',+x.dataset.id===s.id))}
audio.ontimeupdate=()=>{const s=scenes.find(x=>audio.currentTime>=x.start&&audio.currentTime<x.end)||scenes.at(-1);if(s&&!timeline.querySelector(`.scene[data-id="${s.id}"]`)?.classList.contains('active'))showScene(s);$('#currentTime').textContent=fmt(audio.currentTime);$('#progress').style.width=`${audio.duration?audio.currentTime/audio.duration*100:0}%`};audio.onended=()=>{$('#playBtn').textContent='▶'};
$('#playBtn').onclick=()=>{if(audio.paused){audio.play();$('#playBtn').textContent='Ⅱ'}else{audio.pause();$('#playBtn').textContent='▶'}};
$('#planBtn').onclick=()=>{const data={app:'MatchCut',version:1,voice:voice.files[0]?.name,duration:audio.duration,scenes:scenes.map(s=>({id:s.id,start:+s.start.toFixed(3),end:+s.end.toFixed(3),text:s.text,media:s.media.name}))},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='matchcut-project.json';a.click();URL.revokeObjectURL(url)};
$('#exportBtn').onclick=async()=>{const button=$('#exportBtn'),status=$('#renderStatus');button.disabled=true;status.className='render-status show';status.textContent='FFmpeg đang chuẩn hóa và ghép các cảnh. Video dài có thể mất vài phút…';const form=new FormData();form.append('voice',voice.files[0]);assets.forEach(a=>form.append('media',a.file));form.append('scenes',JSON.stringify(scenes.map(s=>({start:s.start,end:s.end,mediaIndex:assets.indexOf(s.media),mediaType:s.media.type,text:s.text}))));try{const response=await fetch('/api/render',{method:'POST',body:form});if(!response.ok){const data=await response.json();throw new Error(data.error||'Render thất bại')}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='matchcut-output.mp4';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='Đã render xong MP4 và bắt đầu tải xuống.'}catch(error){status.textContent=`Lỗi: ${error.message}. Hãy mở tool bằng ứng dụng MatchCut cục bộ.`}finally{button.disabled=false}};
